parameters.jsCode:
// 1. Get Gemini's text response.
// Handles both common Gemini response shapes.
const raw =
  $json.content?.parts?.[0]?.text ??
  $json.candidates?.[0]?.content?.parts?.[0]?.text ??
  '';

// 2. Clean the response in case Gemini wraps JSON in ```json ... ```
let cleaned = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// 3. Try to convert the JSON text into a real JavaScript object.
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    classification: 'Needs Review',
    score: 0,
    serviceInterest: 'Unknown',
    urgency: 'Unknown',
    budgetSignal: 'Unknown',
    purchaseIntent: 'Unknown',
    reasoning: 'Gemini response could not be parsed properly.'
  };
}

// 4. Helper function to make sure Gemini only returns allowed values.
const normalize = (value, allowed, fallback) => {
  if (!value) return fallback;

  const match = allowed.find(
    option =>
      option.toLowerCase() === String(value).trim().toLowerCase()
  );

  return match || fallback;
};

// 5. Validate classification.
const classification = normalize(
  parsed.classification,
  ['Hot', 'Warm', 'Cold', 'Needs Review'],
  'Needs Review'
);

// 6. Validate urgency.
const urgency = normalize(
  parsed.urgency,
  ['High', 'Medium', 'Low', 'Unknown'],
  'Unknown'
);

// 7. Validate budget signal.
const budgetSignal = normalize(
  parsed.budgetSignal,
  ['Positive', 'Neutral', 'Negative', 'Unknown'],
  'Unknown'
);

// 8. Validate purchase intent.
const purchaseIntent = normalize(
  parsed.purchaseIntent,
  ['Strong', 'Moderate', 'Weak', 'Unknown'],
  'Unknown'
);

// 9. Make sure score is a valid number between 0 and 100.
let score = Number(parsed.score);

if (Number.isNaN(score)) score = 0;

score = Math.max(0, Math.min(100, score));

// 10. Return one clean object containing both lead data and AI analysis.
return [
  {
    json: {
      leadName: $('Normalize Lead Data').item.json.leadName,
      leadEmail: $('Normalize Lead Data').item.json.leadEmail,
      leadPhone: $('Normalize Lead Data').item.json.leadPhone,
      companyName: $('Normalize Lead Data').item.json.companyName,
      companyWebsite: $('Normalize Lead Data').item.json.companyWebsite,
companyDomain: $('Normalize Lead Data').item.json.companyDomain,
      leadMessage: $('Normalize Lead Data').item.json.leadMessage,
      leadSource: $('Normalize Lead Data').item.json.leadSource,
      createdAt: $('Normalize Lead Data').item.json.createdAt,

      classification,
      leadScore: score,
      serviceInterest: parsed.serviceInterest || 'Unknown',
      urgency,
      budgetSignal,
      purchaseIntent,
      reasoning: parsed.reasoning || 'No reasoning returned.'
    }
  }
];

